    func toggle(_ id: String) {
        let target = !(tracks[id] ?? false)
        let gen = generation
        let wasRemoved = removed.contains(id)
        tracks[id] = target
        if target { removed.remove(id) } else { removed.insert(id) }
        Task {
            do {
                try await setFavourite(kind: .track, id: id, favourite: target)
